var b=WebApplication.CreateBuilder(args);b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen();b.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));var app=b.Build();app.UseCors();app.UseSwagger();app.UseSwaggerUI();app.MapGet("/health/live",()=>Results.Ok(new{status="live"}));app.MapGet("/health/ready",()=>Results.Ok(new{status="ready"}));app.MapGet("/api/v1/warehouses",()=>Results.Ok(new[]{new{id="WH-BKK-01",name="Bangkok Distribution"}}));app.MapGet("/api/v1/items",(string? warehouseId)=>Results.Ok(new[]{new{id="ITEM-204",name="Pallet scanner",warehouseId=warehouseId??"WH-BKK-01"}}));app.MapGet("/api/v1/inventory",()=>Results.Ok(new[]{new{itemId="ITEM-204",quantity=18,status="available"}}));app.MapGet("/api/v1/receiving",()=>Results.Ok(Array.Empty<object>()));app.MapGet("/api/v1/picking",()=>Results.Ok(Array.Empty<object>()));app.MapGet("/api/v1/work-orders",()=>Results.Ok(new[]{new{id="WO-4821",status="open"}}));app.MapGet("/api/v1/twin/scenes/{warehouseId}",(string warehouseId)=>Results.Ok(new{warehouseId,coordinateSystem="warehouse-floor",revision="demo-1",entities=new[]{new{id="F-204",type="forklift",x=1,y=.4,z=.5,confidence=.94}}}));app.Run();
